// Le topic porte le siteId : sesame/{siteId}/doorbell/ring (§4).
const siteId = (msg.topic || '').split('/')[1];
if (!siteId || !msg.payload || !msg.payload.ringId) {
    node.warn('Sonnerie ignorée : topic ou payload invalide');
    return null;
}

msg.sesame = {
    siteId: siteId,
    title: 'Quelqu\'un sonne',
    body: 'Appui sur la sonnette du portail.'
};
node.status({ fill: 'blue', shape: 'dot', text: msg.payload.ringId });
return msg;

const crypto = global.get('crypto');
const fs = global.get('fs');

const KEY_FILE = '/data/firebase-service-account.json';
const AUD = 'https://oauth2.googleapis.com/token';
const SCOPE = 'https://www.googleapis.com/auth/firebase.messaging';

let key;
try {
    key = JSON.parse(fs.readFileSync(KEY_FILE, 'utf8'));
} catch (e) {
    node.error('Clé de compte de service illisible : ' + e.message, msg);
    return null;
}

// project_id vient du fichier de clé : une variable d'environnement de moins
// à tenir à jour, et aucun risque de désaccord entre les deux.
msg.sesame.projectId = key.project_id;

const b64 = (o) => Buffer.from(JSON.stringify(o)).toString('base64url');
const now = Math.floor(Date.now() / 1000);
const unsigned = b64({ alg: 'RS256', typ: 'JWT' }) + '.' + b64({
    iss: key.client_email,
    scope: SCOPE,
    aud: AUD,
    iat: now,
    exp: now + 3600
});
const signature = crypto.createSign('RSA-SHA256')
    .update(unsigned)
    .sign(key.private_key, 'base64url');

// Un jeton neuf à chaque sonnerie : on sonne rarement, et gérer un cache avec
// son expiration coûterait plus en complexité que l'échange lui-même.
msg.url = AUD;
msg.headers = { 'content-type': 'application/x-www-form-urlencoded' };
msg.payload = new URLSearchParams({
    grant_type: 'urn:ietf:params:oauth:grant-type:jwt-bearer',
    assertion: unsigned + '.' + signature
}).toString();
return msg;

const token = msg.payload && msg.payload.access_token;
if (!token) {
    node.error('Jeton OAuth absent : ' + JSON.stringify(msg.payload).slice(0, 300), msg);
    return null;
}

msg.url = 'https://fcm.googleapis.com/v1/projects/' + msg.sesame.projectId + '/messages:send';
msg.headers = {
    'content-type': 'application/json',
    authorization: 'Bearer ' + token
};
msg.payload = {
    message: {
        // Topic FCM = siteId opaque : aucun identifiant utilisateur dans le
        // routage des messages (§10).
        topic: msg.sesame.siteId,
        // Bloc `notification` : Android l'affiche lui-même, app fermée, sans
        // avoir à réveiller notre code.
        notification: { title: msg.sesame.title, body: msg.sesame.body },
        android: { priority: 'HIGH' }
    }
};
return msg;
